}

// Recovery system for abandoned cards
const RECOVERY_STORAGE_KEY = 'celebrait_card_recovery';
const RECOVERY_EXPIRY_DAYS = 7;

// Save progress to localStorage
const saveRecoveryProgress = (data: any) => {
  try {
    // Mobile optimization: Exclude heavy photo data that can block webview main thread
    const { uploadedPhotoIds, photoData, photo_upload, ...lightData } = data.answers || {};

    const recoveryData = {
      ...data,
      answers: {
        ...lightData,
        // Keep only metadata for photos, not the actual Base64 data
        ...(uploadedPhotoIds?.length && { hasUploadedPhotos: true, photoCount: uploadedPhotoIds.length })
      },
      timestamp: Date.now(),
      expiresAt: Date.now() + (RECOVERY_EXPIRY_DAYS * 24 * 60 * 60 * 1000)
    };

    const dataString = JSON.stringify(recoveryData);
    console.log(`[RECOVERY] Saving ${Math.round(dataString.length / 1024)}KB to localStorage`);
    localStorage.setItem(RECOVERY_STORAGE_KEY, dataString);
  } catch (error) {
    console.error('Failed to save recovery progress:', error);
  }
};

// Load progress from localStorage
const loadRecoveryProgress = () => {
  try {
    const saved = localStorage.getItem(RECOVERY_STORAGE_KEY);
    if (!saved) return null;

    const data = JSON.parse(saved);
    if (Date.now() > data.expiresAt) {
      localStorage.removeItem(RECOVERY_STORAGE_KEY);
      return null;
    }
    return data;
  } catch (error) {
    console.error('Failed to load recovery progress:', error);
    return null;
  }
};

// Clear recovery progress
const clearRecoveryProgress = () => {
  try {
    localStorage.removeItem(RECOVERY_STORAGE_KEY);
  } catch (error) {
    console.error('Failed to clear recovery progress:', error);
  }
};

// 12-Phase Creative Journey Component
interface CreativeJourneyLoadingProps {
  answers: Record<string, any>;
}

const CreativeJourneyLoading = ({ answers }: CreativeJourneyLoadingProps) => {
  const [currentPhase, setCurrentPhase] = useState(0);
  const [phaseProgress, setPhaseProgress] = useState(0);
  const [showPackaging, setShowPackaging] = useState(false);

  // Scroll to top when component mounts (mobile optimization)
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  // Auto-scroll popup to top when it opens (removed as this is handled in main component)

  // 12-Phase Creative Journey Definition
  const creativePhases = [
    // FRONT CARD CREATION (8 phases)
    { 
      id: 'photo_analysis', 
      title: 'Analyzing Your Photo', 
      description: `Studying the lighting, composition, and unique features that make ${answers.name || 'them'} special`,
      icon: Scan, 
      color: 'from-purple-500 to-pink-500',
      section: 'Front Card Creation' 
    },
    { 
      id: 'scene_planning', 
      title: 'Planning the Scene', 
      description: `Designing the perfect ${answers.celebration || 'celebration'} environment and setting`,
      icon: Map, 
      color: 'from-pink-500 to-rose-500',
      section: 'Front Card Creation' 
    },
    { 
      id: 'initial_sketching', 
      title: 'Initial Sketching', 
      description: 'Creating the foundational composition and artistic layout',
      icon: PenTool, 
      color: 'from-rose-500 to-orange-500',
      section: 'Front Card Creation' 
    },
    { 
      id: 'base_scene', 
      title: 'Building Base Scene', 
      description: 'Constructing the background world and atmospheric elements',
      icon: Layers, 
      color: 'from-orange-500 to-amber-500',
      section: 'Front Card Creation' 
    },
    { 
      id: 'face_perfection', 
      title: 'Perfecting Faces', 
      description: `Capturing ${answers.name || 'their'} authentic likeness and joyful expression`,
      icon: Focus, 
      color: 'from-amber-500 to-yellow-500',
      section: 'Front Card Creation' 
    },
    { 
      id: 'color_lighting', 
      title: 'Color & Lighting', 
      description: 'Applying the perfect palette and atmospheric lighting effects',
      icon: Sun, 
      color: 'from-yellow-500 to-lime-500',
      section: 'Front Card Creation' 
    },
    { 
      id: 'fine_details', 
      title: 'Adding Fine Details', 
      description: 'Enhancing textures, shadows, and intricate artistic elements',
      icon: Settings, 
      color: 'from-lime-500 to-green-500',
      section: 'Front Card Creation' 
    },
    { 
      id: 'typography_front', 
      title: 'Typography Integration', 
      description: 'Weaving your message naturally into the artistic composition',
      icon: Type, 
      color: 'from-green-500 to-emerald-500',
      section: 'Front Card Creation' 
    },

    // INSIDE CARD CREATION (4 phases)
    { 
      id: 'front_analysis', 
      title: 'Studying Front Design', 
      description: 'Analyzing the front card to ensure perfect visual harmony',
      icon: Search, 
      color: 'from-emerald-500 to-teal-500',
      section: 'Inside Card Creation' 
    },
    { 
      id: 'color_matching', 
      title: 'Color Matching', 
      description: 'Ensuring seamless color consistency between front and inside',
      icon: RefreshCw, 
      color: 'from-teal-500 to-cyan-500',
      section: 'Inside Card Creation' 
    },
    { 
      id: 'typography_harmony', 
      title: 'Typography Harmony', 
      description: 'Matching text styles for a cohesive design language',
      icon: AlignCenter, 
      color: 'from-cyan-500 to-blue-500',
      section: 'Inside Card Creation' 
    },
    { 
      id: 'final_assembly', 
      title: 'Final Assembly', 
      description: 'Polishing and packaging your one-of-a-kind masterpiece',
      icon: Package, 
      color: 'from-blue-500 to-purple-500',
      section: 'Inside Card Creation' 
    },
  ];

  // Phase timing (12.5 seconds per phase = 2.5 minutes total)
  const [showRobotLoading, setShowRobotLoading] = useState(false);

  useEffect(() => {
    // Check if main generation is complete, show robot loading animation instead of packaging
    if (currentPhase >= creativePhases.length - 1 && phaseProgress >= 100 && !showRobotLoading) {
      setTimeout(() => setShowRobotLoading(true), 500);
      return;
    }

    // Don't start interval if we've completed all phases and are showing robot loading
    if (showRobotLoading) {
      return;
    }

    const phaseInterval = setInterval(() => {
      setPhaseProgress(prev => {
        if (prev >= 100) {
          setCurrentPhase(current => {
            if (current < creativePhases.length - 1) {
              return current + 1;
            }
            return current; // Stay at last phase
          });
          return currentPhase < creativePhases.length - 1 ? 0 : 100; // Keep at 100% for final phase
        }
        return prev + (100 / 12.5); // 12.5 seconds per phase (2.5 minutes total)
      });
    }, 1000); // Update every second

    return () => clearInterval(phaseInterval);
  }, [currentPhase, phaseProgress, showRobotLoading]);

  const currentPhaseData = creativePhases[currentPhase];
  const overallProgress = Math.min(100, ((currentPhase * 100 + phaseProgress) / creativePhases.length));
  const frontCardComplete = currentPhase >= 8;
  const isComplete = currentPhase >= creativePhases.length - 1 && phaseProgress >= 100;

