          setSafetyError(null);
          actuallyGenerateCard();
        }}
        errorTitle={safetyError?.title}
        errorMessage={safetyError?.message}
        errorKind={safetyError?.kind as any}
        errorCode={safetyError?.code}
      />
    </div>
  );
}

