import { useState, useEffect } from 'react';
import { useParams } from 'wouter';
import Header from '@/components/header';
import Footer from '@/components/footer';
import CardPreview from '@/components/card-preview';
import { useToast } from '@/hooks/use-toast';

export default function CardPreviewPage() {
  const { reference } = useParams();
  const { toast } = useToast();

  const [cardData, setCardData] = useState<any>(null);
  const [loading, setLoading] = useState(true); // Start with true to prevent "Card Not Found" flash
  const [hasInitialized, setHasInitialized] = useState(false);

  useEffect(() => {
    if (reference && !hasInitialized) {
      setHasInitialized(true);
      // For email ready references, try to load immediately from cache
      if (reference.startsWith('celebrait_ready_')) {
        loadCardDataInstantly();
      } else {
        loadCardData();
      }
    }
  }, [reference, hasInitialized]);

  const loadCardDataInstantly = async () => {
    // For email links, prioritize instant loading
    const cacheKey = `ready_${reference}`;
    try {
      const cached = sessionStorage.getItem(cacheKey);
      if (cached) {
        const parsedData = JSON.parse(cached);
        const card = parsedData.card || parsedData;
        if (card && (card.id || card.conversationData)) {
          setCardData(card);
          setLoading(false); // Hide loading state since we have data
          console.log(`[INSTANT] Email card preview loaded from cache: ${cacheKey}`);

          // Preload images for instant display
          if (card.id) {
            const frontImg = new Image();
            const insideImg = new Image();
            frontImg.src = `/api/cards/${card.id}/fast-front-image`;
            if (card.insideImageUrl) {
              insideImg.src = `/api/cards/${card.id}/fast-inside-image`;
            }
          }
          return;
        }
      }
    } catch (e) {
      console.warn('Cache load failed, falling back to API');
    }

    // No cache found - load from API but don't show loading spinner for email links
    try {
      const response = await fetch(`/api/cards/ready/${reference}`);
      if (response.ok) {
        const data = await response.json();
        const card = data.card || data;
        setCardData(card);
        setLoading(false); // Hide loading state since we have data

        // Cache for next time
        sessionStorage.setItem(cacheKey, JSON.stringify(data));

        // Preload images for instant display
        if (card.id) {
          const frontImg = new Image();
          const insideImg = new Image();
          frontImg.src = `/api/cards/${card.id}/fast-front-image`;
          if (card.insideImageUrl) {
            insideImg.src = `/api/cards/${card.id}/fast-inside-image`;
          }
        }

        console.log(`[INSTANT] Email card loaded from API and cached: ${cacheKey}`);
      } else {
        console.error('Failed to load email card data');
        setLoading(false); // Show "Card Not Found" since API failed
      }
    } catch (error) {
      console.error('Error loading email card:', error);
      setLoading(false); // Show "Card Not Found" since we have no data
    }
  };

  const loadCardData = async () => {
    try {
      // PARALLEL OPTIMIZATION: Start API call immediately alongside cache check
      let apiPromise: Promise<Response> | null = null;
      let cacheHit = false;

      // Start API call immediately (don't wait for cache check)
      if (reference?.startsWith('celebrait_ready_')) {
        apiPromise = fetch(`/api/cards/ready/${reference}`);
      } else if (reference) {
        apiPromise = fetch(`/api/cards/${reference}/fast-metadata`);
      }

      // PARALLEL: Check cache while API call is in flight
      const cacheKeys = [
        `ready_${reference}`,
        `card_${reference}`,
        'cardPreviewData'
      ];

      for (const key of cacheKeys) {
        try {
          const cached = sessionStorage.getItem(key);
          if (cached) {
            const parsedData = JSON.parse(cached);
            const card = parsedData.card || parsedData;
            if (card && (card.id || card.conversationData)) {
              setCardData(card);
              setLoading(false);
              cacheHit = true;
              // Don't abort - let request complete to avoid runtime errors
              console.log(`[INSTANT] Card preview loaded from cache: ${key} - API call will be ignored`);

              // PARALLEL: Start image preloading immediately
              if (card.id) {
                Promise.all([
                  new Promise<void>((resolve) => {
                    const frontImg = new Image();
                    frontImg.onload = () => resolve();
                    frontImg.onerror = () => resolve();
                    frontImg.src = `/api/cards/${card.id}/fast-front-image`;
                  }),
                  card.insideImageUrl ? new Promise<void>((resolve) => {
                    const insideImg = new Image();
                    insideImg.onload = () => resolve();
                    insideImg.onerror = () => resolve();
                    insideImg.src = `/api/cards/${card.id}/fast-inside-image`;
                  }) : Promise.resolve()
                ]).then(() => {
                  console.log('[PARALLEL] Images preloaded');
                });
              }

              return;
            }
          }
        } catch (e) {
          // Continue to next cache key
        }
      }

      // If cache miss, wait for API call and show loading
      if (!cacheHit && apiPromise) {
        setLoading(true);

        const response = await apiPromise;

        if (response.ok) {
          const data = await response.json();
          const card = data.card || data; // Handle both response formats
          setCardData(card);

          // PARALLEL: Start image preloading immediately with metadata loading
          const imagePreloadPromises: Promise<void>[] = [];

          if (card.id) {
            // Front image preload
            imagePreloadPromises.push(
              new Promise<void>((resolve) => {
                const frontImg = new Image();
                frontImg.onload = () => resolve();
                frontImg.onerror = () => resolve();
                frontImg.src = `/api/cards/${card.id}/fast-front-image`;
              })
            );

            // Inside image preload (if exists)
            if (card.insideImageUrl) {
              imagePreloadPromises.push(
                new Promise<void>((resolve) => {
                  const insideImg = new Image();
                  insideImg.onload = () => resolve();
                  insideImg.onerror = () => resolve();
                  insideImg.src = `/api/cards/${card.id}/fast-inside-image`;
                })
              );
            }
          }

          // PARALLEL: Cache operations alongside image preloading
          const cachePromise = Promise.resolve().then(async () => {
            try {
              sessionStorage.setItem('cardPreviewData', JSON.stringify(card));
              sessionStorage.setItem(`ready_${reference}`, JSON.stringify(data));
              sessionStorage.setItem(`card_${reference}`, JSON.stringify(card));

              // Additional cache entries for different reference formats
              if (reference?.startsWith('celebrait_ready_')) {
                const cardId = reference.split('_')[2];
                sessionStorage.setItem(`card_${cardId}`, JSON.stringify(card));
              }

              console.log('[PARALLEL] Cache operations completed');
            } catch (storageError) {
              console.warn('Failed to preload delivery choice data:', storageError);
            }
          });

          // Wait for all parallel operations (non-blocking for UI)
          Promise.all([...imagePreloadPromises, cachePromise]).then(() => {
            console.log('[PARALLEL] All optimization operations completed');
          });

          setLoading(false);
        } else {
          console.error('Failed to fetch card data:', response.status, response.statusText);
          toast({
            title: 'Error',
            description: 'Unable to load card data',
            variant: 'destructive'
          });
        }
      }
    } catch (error) {
      console.error('Error loading card data:', error);
      toast({
        title: 'Error',
        description: 'Unable to load card data',
        variant: 'destructive'
      });
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50">
        <Header />
        <div className="flex items-center justify-center min-h-[60vh]">
          <div className="text-center space-y-4">
            <div className="animate-spin w-12 h-12 border-4 border-purple-200 border-t-purple-600 rounded-full mx-auto"></div>
            <p className="text-lg text-gray-600">Loading your card...</p>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  if (!cardData) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50">
        <Header />
        <div className="flex items-center justify-center min-h-[60vh]">
          <div className="text-center space-y-4">
            <h2 className="text-2xl font-bold text-gray-800">Card Not Found</h2>
            <p className="text-gray-600">Unable to load the card data.</p>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  // Create mock onboarding object for CardPreview component
  const mockOnboarding = {
    currentStep: 4, // Assuming this is the final step
    userName: 'Valued Customer',
    selectedDelivery: cardData.cardType || 'printed'
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50">
      <Header />

      <main className="container mx-auto px-4 py-8">
        <CardPreview 
          card={cardData} 
          onboarding={mockOnboarding}
        />
      </main>

      <Footer />
    </div>
  );
}

client/src/components/ui/ai-brainstorm-c.content:
import { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Bot, User, Sparkles, Loader2, MessageCircle, X, Send, ArrowUp } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { TypingAnimation } from "@/components/ui/typing-animation";

interface AIBrainstormChatProps {
  type: "scene" | "art_style";
  recipientName: string;
  celebration: string;
  currentInput: string;
  onSuggestionSelect: (suggestion: string) => void;
  buttonText?: string;
  buttonIcon?: React.ReactNode;
  photoContext?: string;
}

interface ConversationState {
  currentStep: 'setting' | 'activity' | 'people' | 'extra_detail' | 'final_approval';
  settingRefinements: number; // Track number of location refinement questions asked
  collectedInfo: {
    setting?: string;
    activity?: string;
    people?: string;
    extraDetail?: string;
  };
}

interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
  isTyping?: boolean;
}

export function AIBrainstormChat({ 
  type, 
  recipientName, 
  celebration, 
  currentInput, 
  onSuggestionSelect,
  buttonText = "Get AI Help",
  buttonIcon = <Bot className="w-4 h-4" />,
  photoContext = ""
}: AIBrainstormChatProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [conversationState, setConversationState] = useState<ConversationState>({
    currentStep: 'setting',
    settingRefinements: 0,
    collectedInfo: {}
  });
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { toast } = useToast();

  // Auto-scroll to bottom when new messages are added AND during typing
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isLoading]);

  // Auto-scroll during typing animation
  useEffect(() => {
    const interval = setInterval(() => {
      if (messages.some(msg => msg.isTyping)) {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
      }
    }, 100); // Scroll every 100ms during typing

    return () => clearInterval(interval);
  }, [messages]);

  // Initialize with auto-typing AI greeting message when dialog opens
  useEffect(() => {
    if (isOpen && messages.length === 0) {
      const initialMessage: ChatMessage = {
        role: "assistant",
        content: getInitialMessage(),
        timestamp: new Date(),
        isTyping: true
      };

      setMessages([initialMessage]);

      // Simulate typing completion
      const typingTimeout = setTimeout(() => {
        setMessages(prev => 
          prev.map(msg => 
            msg.timestamp === initialMessage.timestamp 
              ? { ...msg, isTyping: false }
              : msg
          )
        );
      }, initialMessage.content.length * 15); // 15ms per character for moderate typing speed

      return () => clearTimeout(typingTimeout);
    } else if (!isOpen) {
      // Reset when dialog closes
      setMessages([]);
      setConversationState({
        currentStep: 'setting',
        settingRefinements: 0,
        collectedInfo: {}
      });
    }
  }, [isOpen]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || isLoading) return;

    const userMessage: ChatMessage = {
      role: "user",
      content: userInput,
      timestamp: new Date()
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    setIsLoading(true);

    try {
      // Convert messages to OpenAI format for conversation history
      const conversationHistory = newMessages.map(msg => ({
        role: msg.role,
        content: msg.content
      }));

      const response = await apiRequest("POST", "/api/ai-brainstorm", {
        type,
        context: `Current input: "${currentInput}"`,
        userInput,
        recipientName,
        celebration,
        conversationStep: conversationState.currentStep,
        settingRefinements: conversationState.settingRefinements,
        conversationHistory: conversationHistory.slice(0, -1), // Exclude the current message
        photoContext
      });

      const result = await response.json();

      // Add typing animation message
      const typingMessage: ChatMessage = {
        role: "assistant",
        content: result.response,
        timestamp: new Date(),
        isTyping: true
      };

      setMessages(prev => [...prev, typingMessage]);
      setUserInput("");

      // Update conversation state - collect the user's input for current step
      setConversationState(prev => {
        const newState = { ...prev };

        // Check if AI response indicates final approval stage
        const aiResponse = result.response || '';
        const isFinalApprovalResponse = aiResponse.includes("When you're ready to proceed") || 
                                       aiResponse.includes("click 'Sounds great, let's go!'") ||
                                       aiResponse.includes("art style selection") ||
                                       aiResponse.includes("complete scene description") ||
                                       aiResponse.includes("final scene") ||
                                       aiResponse.includes("scene description") ||
                                       aiResponse.includes("ready to move") ||
                                       aiResponse.includes("Let's move on to");

        if (isFinalApprovalResponse) {
          newState.currentStep = 'final_approval';
          return newState;
        }

        // Don't advance step if user is asking for ideas
        if (userInput.toLowerCase().includes('get ideas') || userInput.toLowerCase().includes('more ideas')) {
          return newState; // Stay on same step
        }

        // Store the user's input for the current step and advance if it's a real answer
        switch (prev.currentStep) {
          case 'setting':
            if (!userInput.toLowerCase().includes('get ideas') && !userInput.toLowerCase().includes('more ideas')) {
              // Update setting info and track refinement count
              newState.collectedInfo.setting = userInput;
              newState.settingRefinements = prev.settingRefinements + 1;

              // Only advance to activity after 2 refinement questions
              if (prev.settingRefinements >= 2) {
                newState.currentStep = 'activity';
              }
            }
            break;
          case 'activity':
            if (!userInput.toLowerCase().includes('get ideas') && !userInput.toLowerCase().includes('more ideas')) {
              newState.collectedInfo.activity = userInput;
              newState.currentStep = 'people';
            }
            break;
          case 'people':
            if (!userInput.toLowerCase().includes('get ideas') && !userInput.toLowerCase().includes('more ideas')) {
              newState.collectedInfo.people = userInput;
              newState.currentStep = 'extra_detail';
            }
            break;
          case 'extra_detail':
            if (userInput.toLowerCase().includes('skip')) {
              newState.currentStep = 'final_approval';
            } else if (!userInput.toLowerCase().includes('get ideas') && !userInput.toLowerCase().includes('more ideas')) {
              newState.collectedInfo.extraDetail = userInput;
              newState.currentStep = 'final_approval';
            }
            break;
          case 'final_approval':
            // If user approves, generate final scene description and auto-submit
            if (userInput.toLowerCase().includes('yes') || userInput.toLowerCase().includes('approve') || userInput.toLowerCase().includes('perfect')) {
              const finalScene = `${newState.collectedInfo.setting || ''} ${newState.collectedInfo.activity || ''} ${newState.collectedInfo.people || ''} ${newState.collectedInfo.extraDetail || ''}`.trim();
              setTimeout(() => {
                onSuggestionSelect(finalScene);
                setIsOpen(false);
              }, 1000);
            }
            break;
          case 'change_request':
            // User has specified what they want to change
            // Keep in change_request state until they provide the new information
            // Then return to final_approval
            newState.currentStep = 'final_approval';
            break;
        }

        return newState;
      });

    } catch (error) {
      console.error('AI brainstorm error:', error);
      toast({
        title: "Error",
        description: "Failed to get AI suggestions. Please try again.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const getInitialMessage = () => {
    // Analyze photo context to determine if we're dealing with single person or multiple people
    const isMultiplePeople = photoContext && (
      photoContext.toLowerCase().includes('multiple photos') ||
