                          </p>
                        </div>
                      </div>
                    ) : (
                      <div className="aspect-square bg-gray-50 rounded-lg flex items-center justify-center">
                        <p className="text-gray-500">Upload photo and select style to transform</p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

