export async function sendEmail(params: EmailParams): Promise<boolean> {
  try {
    await sgMail.send({
      to: params.to,
      from: params.from,
      subject: params.subject,
      text: params.text || 'Email content is available in HTML format.',
      ...(params.html && { html: params.html }),
